def greedy_generate(prompt, predict, max_tokens, stop="<eos>"):
    context=list(prompt); generated=[]
    for _ in range(max_tokens):
        scores=predict(list(context))
        token=max(scores,key=scores.get)
        if token==stop:
            break
        generated.append(token); context.append(token)
    return generated

