def validate_search_call(call):
    if not isinstance(call,dict) or set(call)!={"name","arguments"} or call["name"]!="search_documents":
        raise ValueError("Tool not allowed")
    args=call["arguments"]
    if not isinstance(args,dict) or set(args)!={"query","limit"}:
