import json

def classify_simulated(text, model):
    messages=[{"role":"system","content":"Classify as billing, technical, or other."},{"role":"user","content":json.dumps({"input":text})}]
    raw=model(messages)
    try:
        data=json.loads(raw)
        if not isinstance(data,dict) or set(data)!={"category"} or data["category"] not in ("billing","technical","other"):
            raise ValueError("Schema mismatch")
    except (ValueError,TypeError):
        return {"mode":"simulated","status":"invalid-response","category":None}
    return {"mode":"simulated","status":"ok","category":data["category"]}

def evaluate_labels(expected, actual):
    if len(expected)!=len(actual):
        raise ValueError("Predictions must align with examples")
    allowed=("billing","technical","other",None)
    invalid=sum(a not in allowed for a in actual)
    correct=sum(a in allowed and a==e for e,a in zip(expected,actual))
    return {"accuracy":correct/len(expected) if expected else 0.0,"invalid":invalid,"abstentions":sum(a is None for a in actual)}

